if(page==='overview')body=!data.cards.length?null:<><PlaidOfferCard gateway={GATEWAY_ORIGIN} collects={collects} gatewayConfigured={gatewayConfigured}/><button type="button" className="ask-card" onClick={()=>go('advisor')}><CapybaraMark size={36}/><span className="ask-card-text">{t('问问卡疲扒拉：这笔用哪张卡？')}</span><RightOutlined className="ask-card-arrow"/></button><PaymentAssistant cards={held.cards} hidden={hidden} urls={urls} onDetail={setDetail} onRefresh={collects?()=>refreshBank():undefined}/><CreditManager cards={held.cards} compact hidden={hidden} onSetFeeDate={openFeeDate}/><PurchaseChooser cards={held.cards} hidden={hidden} onAsk={()=>go('advisor')} onDetail={setDetail} onSettings={()=>go('settings')}/><Collapse style={{marginBottom:20}} items={[{key:'summary',label:t('钱包全貌与积分'),children:summarySection}]}/><Flex justify="center"><Button type="link" onClick={()=>go('wallet')}>{t('查看全部 {0} 张卡',[data.cards.length])}</Button></Flex>
{showArchivedHighlights&&<Row gutter={[20,20]} className="bottom-panels"><Col xs={24} lg={12}><Card title={t("福利使用进度")} extra={<Button type="link" onClick={()=>go('benefits')}>{t("查看全部")}</Button>}>{benefitRows}<Paragraph type="secondary" className="source-note">{t('这里只展示已保存的福利记录。')}</Paragraph></Card></Col><Col xs={24} lg={12}><Card title={t("已添加的优惠")} extra={<Button type="link" onClick={()=>go('offers')}>{t("查看全部")}</Button>}><Space orientation="vertical" size={20} style={{width:'100%'}}>{data.offers.filter(o=>o.status==='added').map(o=><Flex key={`${o.card||'unknown'}|${o.name}`} gap={12} align="center"><BankMark bank="Amex US" size={36}/><div style={{flex:1}}><ItemLogo text={o.name}/><Text strong>{o.name.split(' - ')[0]}</Text><br/><Text type="secondary">{data.cards.find(c=>c.id===o.card)?.name||t('卡片待确认')} · {o.expires||t('到期日未读取')}{t(" 到期")}</Text></div><Button size="small" onClick={()=>setOfferDetail(o)}>{t("详情")}</Button></Flex>)}</Space></Card></Col></Row>}</>;
