if(page==='offers'){const rows=held.offers.filter(o=>(offerStatus==='all'||o.status===offerStatus)&&(!search||o.name.toLowerCase().includes(search.toLowerCase())));body=<><Alert type="info" showIcon title={t('已保存 {0} 项优惠明细',[held.offers.length])} description={t('这里只显示已保存的优惠，银行的总数可能包含尚未读取的条目。')} style={{marginBottom:24}}/><Flex wrap gap={12} justify="space-between" className="filters"><Segmented value={offerStatus} onChange={setOfferStatus} options={[{value:'all',label:t('全部 · {0}',[held.offers.length])},{value:'added',label:t('已添加 · {0}',[held.offers.filter(o=>o.status==='added').length])},{value:'available',label:t('未添加 · {0}',[held.offers.filter(o=>o.status==='available').length])}]}/><Input className="card-search" allowClear prefix={<SearchOutlined/>} placeholder={t("搜索商户")} aria-label={t("搜索优惠")} value={search} onChange={e=>setSearch(e.target.value)}/></Flex><Row gutter={[20,20]}>{rows.map(o=><Col xs={24} md={12} xl={8} key={`${o.card||'unknown'}|${o.name}`}><Card title={<span className="offer-title"><BankMark bank={data.cards.find(c=>c.id===o.card)?.bank||'Amex US'} size={20}/><ItemLogo text={o.name}/><Text ellipsis={{tooltip:o.name}}>{o.name}</Text></span>} extra={<Tag color={o.status==='added'?'success':'default'}>{o.status==='added'?t("已添加"):t('未添加')}</Tag>} actions={[<Button type="link" onClick={()=>setOfferDetail(o)}>{t("查看详情")}</Button>]}><Paragraph style={{minHeight:48}}>{o.summary}</Paragraph><Text type="secondary">{data.cards.find(c=>c.id===o.card)?.name||t('卡片待确认')} · {o.expires||t('到期日未读取')}{t(" 到期")}</Text></Card></Col>)}</Row>{!rows.length&&<Empty description={t("没有匹配的优惠")}/>}</>}
if(page==='transactions'){const rows=held.transactions.filter(r=>(bank==='all'||r.card===bank)&&(!search||r.description.toLowerCase().includes(search.trim().toLowerCase())));const cols=[{title:t("卡片"),dataIndex:'card',width:170,render:v=><CardIdentity card={data.cards.find(c=>c.id===(v||'gold'))}/>},{title:t("状态"),dataIndex:'status',width:100,render:v=><Tag color={v==='pending'?'warning':'default'}>{v==='pending'?t("待入账"):v==='posted'?t("已入账"):t("入账状态未确认")}</Tag>},{title:t("采集日期"),dataIndex:'sourceDate',width:120},{title:t("日期"),dataIndex:'date',width:125,sorter:(a,b)=>a.date.localeCompare(b.date)},{title:t("商户 / 描述"),dataIndex:'description',width:330},{title:t("分类"),dataIndex:'inferred_type',width:120,filters:[{text:t("消费"),value:'purchase'},{text:t("还款"),value:'card_payment'},{text:t("福利抵扣"),value:'benefit_credit'}],onFilter:(v,r)=>r.inferred_type===v,render:v=><Tag color={v==='purchase'?'default':v==='card_payment'?'blue':'success'}>{v==='card_payment'?t("还款"):v==='benefit_credit'?t("福利抵扣"):v==='purchase'?t('消费'):t('待分类')}</Tag>},{title:t("积分标记"),dataIndex:'displayed_label',width:110,render:v=>v==='4X Points'?<Tag color="blue">4× Points</Tag>:'—'},{title:t("金额"),dataIndex:'amount',align:'right',width:145,sorter:(a,b)=>a.amount-b.amount,render:(v,r)=><Text type={v<0?'success':undefined}>{amount(v,r.currency||data.cards.find(c=>c.id===r.card)?.currency||'USD')}</Text>}];body=<Card><div className="transaction-filters"><label><Text type="secondary">{t('卡片')}</Text><Select aria-label={t('按卡片筛选交易')} value={bank} onChange={setBank} options={[{value:'all',label:t('全部卡片')},...[...new Set(held.transactions.map(r=>r.card||'gold'))].map(id=>({value:id,label:<CardIdentity card={data.cards.find(c=>c.id===id)}/>}))]}/></label><label><Text type="secondary">{t('搜索')}</Text><Input className="transaction-search" prefix={<SearchOutlined/>} placeholder={t("搜索交易描述")} aria-label={t("搜索交易")} allowClear value={search} onChange={e=>setSearch(e.target.value)}/></label><Button type="text" disabled={bank==='all'&&!search} onClick={()=>{setBank('all');setSearch('')}}>{t('重置筛选')}</Button></div><Table rowKey={r=>r.id||`${r.card||'gold'}-${r.date}-${r.description}-${r.amount}`} dataSource={rows} columns={cols} scroll={{x:1200}} pagination={{defaultPageSize:15,showSizeChanger:false,showTotal:n=>t("共 {0} 笔交易",[n])}}/><Paragraph type="secondary" className="source-note">{t('仅展示已读取的交易，不代表完整历史。待入账金额可能变化；币种按交易或所属卡片显示。')}</Paragraph></Card>}
